+type blockingReader struct {
+	readStarted chan struct{}
+	unblock     chan struct{}
+
+	once   sync.Once
+	mu     sync.Mutex
+	closed bool
+}
+
+func newBlockingReader() *blockingReader {
+	return &blockingReader{
+		readStarted: make(chan struct{}),
+		unblock:     make(chan struct{}),
+	}
+}
+
+func (r *blockingReader) Read(p []byte) (int, error) {
+	r.once.Do(func() {
+		close(r.readStarted)
+	})
+
+	<-r.unblock
+
+	r.mu.Lock()
+	closed := r.closed
+	r.mu.Unlock()
+
+	if closed {
+		return 0, io.ErrClosedPipe
+	}
+	return 0, io.EOF
+}
+
+func (r *blockingReader) Close() error {
+	r.mu.Lock()
+	alreadyClosed := r.closed
+	r.closed = true
+	r.mu.Unlock()
+
+	// The lock ensures exactly one caller exits with alreadyClosed == false,
+	// so close(r.unblock) is called at most once.
+	if !alreadyClosed {
+		close(r.unblock)
+	}
+	return nil
+}
+
+func (r *blockingReader) isClosed() bool {
+	r.mu.Lock()
+	defer r.mu.Unlock()
+	return r.closed
+}
+
+type chunkReader struct {
+	mu       sync.Mutex
+	chunks   [][]byte
+	closeCnt int
+}
+
+func newChunkReader(chunks ...[]byte) *chunkReader {
+	return &chunkReader{chunks: chunks}
+}
+
+func (r *chunkReader) Read(p []byte) (int, error) {
+	r.mu.Lock()
+	defer r.mu.Unlock()
+
+	if len(r.chunks) == 0 {
+		return 0, io.EOF
+	}
+
+	chunk := r.chunks[0]
+	n := copy(p, chunk)
+	if n < len(chunk) {
+		// Chunk is larger than p: retain the unconsumed tail for the next Read.
+		r.chunks[0] = chunk[n:]
+	} else {
+		r.chunks = r.chunks[1:]
+	}
+	return n, nil
+}
+
+func (r *chunkReader) Close() error {
+	r.mu.Lock()
+	defer r.mu.Unlock()
+	r.closeCnt++
+	return nil
+}
+
+func (r *chunkReader) CloseCount() int {
+	r.mu.Lock()
+	defer r.mu.Unlock()
+	return r.closeCnt
+}
